head.script:
// [FAIL] floatingLayer.setDisabled(true) 호출 시 floatingLayer 자체는 disabled 상태가 되지만
//        내부 자식 컴포넌트(input/button)에는 disabled 가 전파되지 않아 여전히 입력/클릭이 가능하다.
//        (동일 조건의 group 컨테이너는 자식까지 disabled 로 전파됨 → 비교군)

scwin.onpageload = function () {
    // floatingLayer 를 화면에 표시 (기본 숨김 대비)
    if (typeof target_fl !== 'undefined' && target_fl.show) {
        target_fl.show();
    }
    scwin.setReturnValue("[초기 상태] 두 컨테이너 및 자식 모두 활성(enabled). '(1) setDisabled(true)' 후 '(3) 상태 확인' 으로 자식 전파 여부를 비교하세요.");
};



// (1) 두 컨테이너 모두 setDisabled(true)
scwin.btn_disable_onclick = function (e) {
    grp_normal.setDisabled(true);
    target_fl.setDisabled(true);
    scwin.setReturnValue("===== setDisabled(true) 호출 완료 =====");
    scwin.printState();
};



// (2) 두 컨테이너 모두 setDisabled(false)
scwin.btn_enable_onclick = function (e) {
    grp_normal.setDisabled(false);
    target_fl.setDisabled(false);
    scwin.setReturnValue("===== setDisabled(false) 호출 완료 =====");
    scwin.printState();
};



// (3) 상태 확인 : 컨테이너 / 자식 컴포넌트 getDisabled + input DOM disabled 출력
scwin.btn_check_onclick = function (e) {
    scwin.printState();
};



scwin.printState = function () {
    // group (정상 비교군) : 자식까지 전파
    scwin.setReturnValue("[group(정상)] container.getDisabled=" + grp_normal.getDisabled()
        + " / input.getDisabled=" + in_normal.getDisabled()
        + " / button.getDisabled=" + btn_normal_child.getDisabled()
        + " / input DOM disabled=" + scwin.domDisabled("in_normal"));

    // floatingLayer (결함) : 컨테이너만 disabled, 자식 미전파
    scwin.setReturnValue("[floatingLayer(결함)] container.getDisabled=" + target_fl.getDisabled()
        + " / input.getDisabled=" + in_defect.getDisabled()
        + " / button.getDisabled=" + btn_defect_child.getDisabled()
        + " / input DOM disabled=" + scwin.domDisabled("in_defect"));

    scwin.setReturnValue("[기대] 두 컨테이너 모두 자식 input/button.getDisabled 가 컨테이너와 동일해야 함.  [실제] floatingLayer 자식은 false 로 남음(입력 가능).");
    scwin.setReturnValue("");
};



// 컴포넌트 id 로 실제 input DOM 의 disabled 여부 조회
scwin.domDisabled = function (cid) {
    var comp = null;
    try { comp = $p.getComponentById(cid); } catch (err) {}
    if (!comp) return "n/a";
    var el = comp.getElement ? comp.getElement() : null;
    if (el && el.tagName && el.tagName.toLowerCase() === 'input') return el.disabled;
    if (el) {
        var inner = el.querySelector ? el.querySelector('input') : null;
        return inner ? inner.disabled : "n/a";
    }
    return "n/a";
};



// ===== 리턴 값 출력 영역 (body_bottom.xml inline 복사) =====
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};
